#include <bits/stdc++.h>using namespace std;using ll = long long; int main() {        ios::sync_with_stdio(false);    cin.tie(NULL);     int t;    cin >> t;     while(t--) {         int n;        ll p;        cin >> n >> p;         vector<ll> a(n), b(n);         for(int i = 0; i < n; i++) cin >> a[i];        for(int i = 0; i < n; i++) cin >> b[i];         vector<pair<ll,ll>> v;         for(int i = 0; i < n; i++){            v.push_back({b[i], a[i]}); // (cost, capacity)        }         sort(v.begin(), v.end());         ll cost = p;       // inform first person directly        ll informed = 1;   // people who know the news         for(auto [bi, ai] : v){             if(informed >= n) break;             if(bi >= p) break;             ll canShare = min((ll)ai, n - informed);             cost += canShare * bi;            informed += canShare;        }         if(informed < n){            cost += (n - informed) * p;        }         cout << cost << "\n";    }}